.event::before { content: ""; position: absolute; top: 0.25rem; left: -2rem; box-sizing: border-box; width: 1rem; height: 1rem; border: 3px solid var(--cms-color-accent); border-radius: 50%; background: var(--cms-color-surface); }
.event__date { margin: 0; font-weight: 700; color: var(--cms-color-accent-strong); }
